/** First EVENT_SCAN_MAX_BYTES of a run's transcript, or null when it has none (#68 qin=events). */
async function readTranscriptHead(stateDir: string, rec: RunRecord): Promise<string | null> {
  const file = resolveRawTranscript(stateDir, rec);
  if (file === "") return null;
  let fh;
  try {
    fh = await openFile(file, "r");
    const buf = Buffer.alloc(EVENT_SCAN_MAX_BYTES);
    const { bytesRead } = await fh.read(buf, 0, buf.length, 0);
    return buf.subarray(0, bytesRead).toString("utf8");
  } catch {
    return null;
  } finally {
    await fh?.close();
  }
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" }).end(JSON.stringify(body));
}

function jsonError(res: ServerResponse, status: number, message: string): void {
  sendJson(res, status, { error: message });
}

function notFound(res: ServerResponse): void {
  jsonError(res, 404, "not found");
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => chunks.push(c));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

// Embedded asset fallbacks: `bun build` inlines these text imports, so the
// single-file bundle serves the dashboard with no sibling files on disk.
// Under plain `node --import tsx` from the source tree the disk read above
// always succeeds and these dynamic imports never execute (Node itself has
