/** Read a served asset relative to this module. Disk copy first (source
 *  tree / installed package layout); embedded text fallback for the
 *  single-file bundle. Null when the asset does not exist at all. */
async function readAsset(rel: string): Promise<string | null> {
  try {
    return await readFile(new URL(`./${rel}`, import.meta.url), "utf8");
  } catch {
    const embedded = embeddedLoaders[rel];
    if (embedded === undefined) return null;
    try {
      return await embedded();
    } catch {
      return null;
    }
  }
}

function vendorContentType(name: string): string {
  if (name.endsWith(".js")) return "text/javascript; charset=utf-8";
  if (name.endsWith(".css")) return "text/css; charset=utf-8";
  if (name.endsWith(".map")) return "application/json; charset=utf-8";
  return "text/plain; charset=utf-8";
}

/** Full raw AgentEvent with the rendered text attached (client reads .text)
 *  and, for metered agents, the per-frame context reading (`ctx`, see
 *  ./context-frames.ts). Both fields are additive and optional. */
function backlogEvent(
  ev: AgentEvent,
  annotator?: FrameAnnotator | null,
): AgentEvent & { text?: string; ctx?: ContextFrame } {
  const text = eventToText(ev);
  const ctx = annotator?.annotate(ev);
  if (text === null && ctx === undefined) return ev;
  return { ...ev, ...(text === null ? {} : { text }), ...(ctx === undefined ? {} : { ctx }) };
}

function safeSend(ws: WsSocket, payload: string): void {
  try {
    if (ws.readyState === ws.OPEN) ws.send(payload);
  } catch {
    // socket died mid-send; the tailer stops via the close handler
  }
}

function rawToString(msg: RawData): string {
  if (typeof msg === "string") return msg;
  if (Array.isArray(msg)) return Buffer.concat(msg as Buffer[]).toString("utf8");
  if (msg instanceof Buffer) return msg.toString("utf8");
  return Buffer.from(msg as ArrayBuffer).toString("utf8");
}

function isRunLive(stateDir: string, runId: string): boolean {
  const rec = readRunRecord(stateDir, runId);
  if (rec === null) return false;
  return rec.status === "running" && Date.now() - (rec.updatedAt ?? 0) <= NOT_LIVE_AFTER_MS;
}

export async function startWebServer(opts: WebServerOptions): Promise<WebServerHandle> {
  // createRunEventHub() takes no source param, so a configured source is
  // injected through the class constructor; passing undefined selects the
  // historical FsRunSource default (behavior identical to pre-0.8.0).
  const hub = new RunEventHub(opts.stateDir, opts.runSource);
  const listWindow = opts.listWindow;
  /** #202: page one plus the transcript backfill progress, when there is one. */
  const windowView = (records: RunRecord[]) => {
    const win = windowRuns(records, listWindow!);
    const scan = hub.scanProgress();
    return scan === undefined ? win : { ...win, scan };
  };
  if (listWindow !== undefined) hub.setRunsView(windowView);

  /** True when the current source reports this run as external — no local
   *  process exists to attach a PTY to. Checked against the source snapshot
   *  (not the fs-only readRunRecord) so external records are covered. */
  function isExternalRun(runId: string): boolean {
    const rec = hub.snapshotRuns().find((r) => r.runId === runId);
    // Imported (#25) runs are past transcripts: no local process either.
    return rec?.source === "external" || rec?.source === "imported";
  }

  const tailers = new Set<ReturnType<typeof setInterval>>();
  const ownsPty = opts.ptyManager === undefined;
  const ptyManager = opts.ptyManager ?? new PtyManager();

  const sockets = new Set<DashSocket>();
  const topics = new Map<string, Set<DashSocket>>();

  const publisher: WsPublisher = {
    publish(topic: string, data: string): void {
      const subs = topics.get(topic);
      if (subs === undefined) return;
      for (const ms of subs) safeSend(ms.ws, data);
    },
  };
  hub.attach(publisher);

  function subscribe(ms: DashSocket, topic: string): void {
    ms.topics.add(topic);
    let subs = topics.get(topic);
    if (subs === undefined) {
      subs = new Set();
      topics.set(topic, subs);
    }
    subs.add(ms);
  }

  function detachPtySocket(ms: DashSocket): void {
    const data = ms.data as PtySocketData;
    data.closed = true;
    data.offData?.();
    data.offExit?.();
    data.offData = null;
    data.offExit = null;
  }

  function openPtySocket(ms: DashSocket): void {
    const data = ms.data as PtySocketData;
    const sessionId = data.sessionId;
    const info = ptyManager.get(sessionId);
    if (info === null) {
      safeSend(ms.ws, JSON.stringify({ type: "exit", exitCode: null }));
      ms.ws.close();
      return;
    }
    const back = ptyManager.scrollback(sessionId);
    if (back.length > 0) safeSend(ms.ws, back);
    if (!info.alive) {
      data.closed = true;
      safeSend(ms.ws, JSON.stringify({ type: "exit", exitCode: info.exitCode ?? null }));
      ms.ws.close();
      return;
    }
    data.offData = ptyManager.onData(sessionId, (chunk) => {
      if (!data.closed) safeSend(ms.ws, chunk);
    });
    data.offExit = ptyManager.onExit(sessionId, (exitCode) => {
      if (data.closed) return;
      detachPtySocket(ms);
      safeSend(ms.ws, JSON.stringify({ type: "exit", exitCode }));
      ms.ws.close();
    });
  }

  function openLivePtySocket(ms: DashSocket): void {
    const data = ms.data as LivePtySocketData;
    void connectLive(data.socket, {
      // The hello comes first: a socket owned by another run (a stale or
      // forged entry) is refused before any of its output reaches the pane.
      onHello: (h) => {
        if (data.closed || h.runId === data.runId) return;
        data.closed = true;
        data.client?.close();
        safeSend(ms.ws, JSON.stringify({ type: "exit", exitCode: null }));
        ms.ws.close();
      },
      // The first frame is always the scrollback resync (term-pane resets on it).
      onScrollback: (d) => {
        if (!data.closed) safeSend(ms.ws, d);
      },
      onOut: (d) => {
        if (!data.closed) safeSend(ms.ws, d);
      },
      onExit: (exitCode) => {
        if (data.closed) return;
        data.closed = true;
        safeSend(ms.ws, JSON.stringify({ type: "exit", exitCode }));
        ms.ws.close();
      },
      onClose: () => {
        if (data.closed) return;
        data.closed = true;
        safeSend(ms.ws, JSON.stringify({ type: "exit", exitCode: null }));
        ms.ws.close();
      },
    }).then(
      (client) => {
        if (data.closed) {
          client.close();
          return;
        }
        data.client = client;
        // Keys typed while the socket was connecting, in order.
        data.pending.drain((msg) => handleLivePtyMessage(ms, msg));
      },
      () => {
        data.closed = true;
        safeSend(ms.ws, JSON.stringify({ type: "exit", exitCode: null }));
        ms.ws.close();
      },
    );
  }

  function handleLivePtyMessage(ms: DashSocket, msg: string): void {
    const data = ms.data as LivePtySocketData;
    if (data.client === null) {
      // Not connected yet: hold the message (bounded) rather than drop it.
      if (!data.closed) data.pending.hold(msg);
      return;
    }
    if (msg.startsWith("{")) {
      try {
        const ctrl = JSON.parse(msg) as { type?: unknown; cols?: unknown; rows?: unknown };
        if (ctrl !== null && typeof ctrl === "object" && ctrl.type === "resize") {
          const cols = Number(ctrl.cols);
          const rows = Number(ctrl.rows);
          if (Number.isInteger(cols) && cols > 0 && Number.isInteger(rows) && rows > 0) data.client.resize(cols, rows);
          return;
        }
      } catch {
        // not a control frame; raw keystrokes below
      }
    }
    data.client.input(msg);
  }

  function handlePtyMessage(ms: DashSocket, msg: string): void {
    const data = ms.data as PtySocketData;
    if (msg.startsWith("{")) {
      try {
        const ctrl = JSON.parse(msg) as { type?: unknown; cols?: unknown; rows?: unknown };
        if (ctrl !== null && typeof ctrl === "object" && ctrl.type === "resize") {
          const cols = Number(ctrl.cols);
          const rows = Number(ctrl.rows);
          if (Number.isInteger(cols) && cols > 0 && Number.isInteger(rows) && rows > 0) {
            ptyManager.resize(data.sessionId, cols, rows);
          }
          return;
        }
      } catch {
        // not a control frame; treat as raw keystrokes below
      }
    }
    ptyManager.write(data.sessionId, msg);
  }

  function sendEnd(ms: DashSocket): void {
    const data = ms.data as RunSocketData;
    if (data.ended) return;
    data.ended 
